// picks generated by Claude. Imported only from route handlers.

import Anthropic from "@anthropic-ai/sdk";
import { z } from "zod";
import { zodOutputFormat } from "@anthropic-ai/sdk/helpers/zod";
import { serviceSupabase } from "./supabase-service";
import { createServerSupabase } from "./supabase";
import {
  ALWAYS_FEATURED,
  LEAGUE_META,
  PICKEM_SEASON,
  seasonWeek,
  weekWindow,
  legLineAndPrice,
  type BestLine,
  type BestLines,
  type HouseCall,
  type HousePicks,
  type League,
  type Market,
  type PickemGame,
} from "./pickem";
import { isPower, unmappedTeams } from "./pickem-conferences";
